const confirmed = {
  instrument: "XAUUSD",
  timeframes: { H4:"Primary direction", H1:"Directional bias", M15:"Buy/sell zones and setup quality", M1:"Entry confirmation" },
  tradeGrades: ["A+","A","B+"],
  mandatory: ["A+ requires trend alignment"],
  methods: ["SMC Broad Chop Multi-Timeframe","BOS / CHoCH","Fair Value Gap (FVG)","Buy-side and sell-side liquidity","Demand / Supply","Support / Resistance","Fibonacci","MACD","Bollinger Bands","EMA 13 / 50 / 200"],
  safeguards: ["Respect provider session breaks and holidays","Handle high-impact USD news","Use only data known at decision time"],
};
const instructions = [
  "Develop versioned, testable candidate rules for Gold AI from the confirmed brief.",
  "Treat any threshold, timeframe role or grade boundary not explicitly confirmed as a hypothesis.",
  "Propose explicit definitions and pseudocode for trend, zone, trigger, invalidation, WAIT, A+, A, B+ and All-in zone eligibility. Treat All-in as a zone label; do not recommend account exposure.",
  "For each rule define required inputs, evaluation timestamp, adverse examples and expected outputs.",
  "Treat the v0.1 result as diagnostic evidence only. Separate observed trade facts from explanations; missing H4/H1/M15/M1 context means the cause of a loss is unknown.",
  "Compare winning and losing examples using only context available at entry. Compare one change at a time, such as allowing M15 zone touch and M1 confirmation to occur on separate closed bars without losing the invalidation boundary.",
  "Treat M15 FVG, liquidity and session filters as testable candidates rather than mandatory criteria. Keep M1 entry-only.",
  "Preserve a chronological holdout. Keep baseline and candidate on identical candles, fills and costs. Report wins, losses, realized payoff, net expectancy in R, drawdown and trade count by trend/countertrend. Diagnose reduced trade counts before calling a candidate sharper.",
  "Return JSON with candidateRules, assumptions, testCases, baseline, evaluationPlan, and openQuestions. Do not invent market data, trade outcomes or strategy performance.",
  "Keep the candidate research-only. It must never become an active trading or member rule automatically."
].join("\n");
return $input.all().map(({json},index)=>{
  if(json.previousEvaluation!=null && typeof json.previousEvaluation!=="object") throw new Error("Expected a structured previous evaluation");
  return {json:{stage:"RESEARCH_ONLY",instructions,confirmed,previousEvaluation:json.previousEvaluation??null, baselineObservation:{version:"v0.1", source:"TradingView OANDA:XAUUSD M1", reportRange:"2026-11-16 to 2026-11-20", trades:11,wins:6,losses:5,side:"SHORT",countertrendTrades:0,ownerDecision:"REJECTED",costVerified:false}},pairedItem:{item:index}};
});
